import { useEffect, useRef } from "react";
import {Map} from "react-kakao-maps-sdk";

const CardItem_Map = (mapx,mapy,mlevel) => {

    //스크립트로 api가져오면 window전역객체로 분류.
    // 함수형 컴포넌트에서는 인식 못함 -> 때문에 변수선언.
    
    console.log(mapx);
    console.log(mapy);
    console.log(mlevel);
    
    return (
        <div className="cardItemMap">
            <Map 
                center = {{lat : mapx, lng : mapy}}
                level = {mlevel}
                style = {{width:'100%',hegiht:"300px"}}
            >
            </Map>
        </div>
    );
}


export default CardItem_Map;
